from pathlib import Path
import json
root=Path('src/content')
def guide(slug,title,cat,desc,mins,version,source,steps,tip,keys=[],shortcuts=[]):
 meta=dict(title=title,category=cat,description=desc,minutes=mins,level='Débutant',version=version,updated='2026-11-24',author='BureauClair — rédaction initiale',source=source,sourceLabel='Documentation Microsoft',keywords=keys,shortcuts=shortcuts)
 body='## Votre objectif\n\n'+desc+'\n\n## Les étapes\n\n'+'\n\n'.join(f'### {i+1}. {t}\n\n{d}' for i,(t,d) in enumerate(steps))+'\n\n## Le bon réflexe\n\n'+tip+'\n\n## Si votre écran est différent\n\nLes intitulés peuvent varier selon la langue, la version et les règles de votre organisation. Vérifiez votre version dans les informations du logiciel. Consultez la documentation liée avant toute modification d’un fichier important.\n'
 (root/'guides'/f'{slug}.md').write_text(json.dumps(meta,ensure_ascii=False)+'\n'+body,encoding='utf-8')
